    /// instead of creating a duplicate. A different interval or payload is
    /// treated as a distinct schedule and creates a new row.
    /// <br /><br />
    /// This makes it safe to call in <c>onStart()</c>, which runs on every Durable
    /// Object wake:
    /// <code lang="ts">
    /// async onStart() {
    ///   // Only one schedule is created, no matter how many times the DO wakes
    ///   await this.scheduleEvery(30, "tick");
    /// }
    /// </code>
    /// </summary>
    /// <remarks>@template T Type of the payload data</remarks>
    /// <param name="intervalSeconds">Number of seconds between executions</param>
    /// <param name="callback">Name of the method to call</param>
    /// <param name="payload">Data to pass to the callback</param>
    /// <param name="options">Options for the scheduled task</param>
    /// <param name="options.retry">Retry options for the callback execution</param>
    /// <returns>Schedule object representing the scheduled task</returns>
    abstract scheduleEvery<'T>: intervalSeconds: float * callback: McpAgent.Queue.Callback * ?payload: 'T * ?options: McpAgent.ScheduleEvery.Options -> JS.Promise<FSharp.CloudEdge.Runtime.AgentsMcpClient.Agent.Schedule.Result.Item>

